public class MemoTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        int[] calls = { 0 };
        java.util.function.Supplier<String> inner = () -> {
            calls[0]++;
            return "value-" + calls[0];
        };
        java.util.function.Supplier<String> cached = Memo.once(inner);
        check("once returns a Supplier", true, cached != null);
        if (cached != null) {
            check("inner not called before first get()", 0, calls[0]);
            check("first get() returns inner result", "value-1", cached.get());
            check("second get() returns cached value", "value-1", cached.get());
            check("third get() still cached", "value-1", cached.get());
            check("inner called exactly once", 1, calls[0]);
        } else {
            check("inner not called before first get()", 0, "skipped -- once returned null");
            check("first get() returns inner result", "value-1", "skipped -- once returned null");
            check("inner called exactly once", 1, "skipped -- once returned null");
        }
        int[] calls2 = { 0 };
        java.util.function.Supplier<String> other = Memo.once(() -> {
            calls2[0]++;
            return "other";
        });
        if (other != null) {
            check("second memo returns its own value", "other", other.get());
            other.get();
            check("memos cache independently", 1, calls2[0]);
        } else {
            check("second memo returns its own value", "other", "skipped -- once returned null");
            check("memos cache independently", 1, "skipped -- once returned null");
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

