public class Memo {

    public static java.util.function.Supplier<String> once(java.util.function.Supplier<String> inner) {
        boolean[] called = { false };
        String[] cache = { null };
        return () -> {
            if (!called[0]) {
                cache[0] = inner.get();
                called[0] = true;
            }
            return cache[0];
        };
    }
}
